// Hand-written, not generated by Speakeasy.

package authlete_test

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"strings"
	"testing"

	authlete "github.com/authlete/authlete-go-sdk"
	"github.com/authlete/authlete-go-sdk/models/components"
	"github.com/authlete/authlete-go-sdk/models/operations"
	"github.com/authlete/authlete-go-sdk/retry"
)

type sent struct {
	url  string
	body map[string]any
}

// recorder captures requests instead of sending them.
type recorder struct{ reqs []sent }

func (r *recorder) Do(req *http.Request) (*http.Response, error) {
	s := sent{url: req.URL.String()}
	if req.Body != nil {
		raw, _ := io.ReadAll(req.Body)
		_ = json.Unmarshal(raw, &s.body)
	}
	r.reqs = append(r.reqs, s)
	return &http.Response{
		StatusCode: 200,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(`{}`)),
		Request:    req,
	}, nil
}

func (r *recorder) last(t *testing.T) sent {
	t.Helper()
	if len(r.reqs) == 0 {
		t.Fatal("no request sent")
	}
	return r.reqs[len(r.reqs)-1]
}

var ctx = context.Background()

func newSDK(rec *recorder, opts ...authlete.SDKOption) *authlete.Authlete {
	base := []authlete.SDKOption{
		authlete.WithSecurity("token"),
		authlete.WithServerURL("https://jp.authlete.com"),
		authlete.WithServiceID("123"),
		authlete.WithClient(rec),
		authlete.WithRetryConfig(retry.Config{Strategy: "none"}),
	}
	return authlete.New(append(base, opts...)...)
}

func create(sdk *authlete.Authlete, apiServerID *int64) {
	_, _ = sdk.Service.Create(ctx, components.ServiceCreateIdpRequest{
		OrganizationID: 1, APIServerID: apiServerID,
		Service: &components.ServiceInput{ServiceName: authlete.Pointer("x")},
	})
}

func TestSaaSAPIServerIDIsDerivedWithoutOptions(t *testing.T) {
	for host, want := range map[string]float64{
		"https://us.authlete.com": 76281,
		"https://jp.authlete.com": 53285,
		"https://eu.authlete.com": 63294,
		"https://br.authlete.com": 47363,
	} {
		rec := &recorder{}
		sdk := authlete.New(authlete.WithSecurity("token"), authlete.WithServerURL(host),
			authlete.WithClient(rec), authlete.WithRetryConfig(retry.Config{Strategy: "none"}))
		create(sdk, nil)
		if got := rec.last(t); got.url != "https://login.authlete.com/api/service" || got.body["apiServerId"] != want {
			t.Errorf("%s: got %s apiServerId=%v, want %v", host, got.url, got.body["apiServerId"], want)
		}
	}
}

func TestDefaultServerIsUS(t *testing.T) {
	rec := &recorder{}
	sdk := authlete.New(authlete.WithSecurity("token"), authlete.WithClient(rec),
		authlete.WithRetryConfig(retry.Config{Strategy: "none"}))
	create(sdk, nil)
	if got := rec.last(t).body["apiServerId"]; got != float64(76281) {
		t.Errorf("apiServerId=%v, want 76281", got)
	}
}

func TestMainAPIIsUnchanged(t *testing.T) {
	rec := &recorder{}
	sdk := newSDK(rec)
	_, _ = sdk.Service.Get(ctx, operations.ServiceGetAPIRequest{})
	if got := rec.last(t); got.url != "https://jp.authlete.com/api/123/service/get" {
		t.Errorf("main API: got %s", got.url)
	}
}

func TestMissingServiceIDFailsBeforeSending(t *testing.T) {
	rec := &recorder{}
	sdk := authlete.New(authlete.WithSecurity("token"), authlete.WithClient(rec),
		authlete.WithRetryConfig(retry.Config{Strategy: "none"}))
	_, err := sdk.Service.Get(ctx, operations.ServiceGetAPIRequest{})
	if err == nil || !strings.Contains(err.Error(), "serviceId is not set") {
		t.Errorf("err=%v, want serviceId is not set", err)
	}
	if len(rec.reqs) != 0 {
		t.Errorf("request was sent: %s", rec.reqs[0].url)
	}
	// IdP operations have no serviceId and are not affected.
	create(sdk, nil)
	if len(rec.reqs) != 1 {
		t.Errorf("IdP create was blocked")
	}
}

func TestAuthleteIDPURLStillDerivesAPIServerID(t *testing.T) {
	rec := &recorder{}
	sdk := newSDK(rec, authlete.WithIDPURL("https://login.authlete.com"))
	create(sdk, nil)
	if got := rec.last(t); got.url != "https://login.authlete.com/api/service" || got.body["apiServerId"] != float64(53285) {
		t.Errorf("got %s apiServerId=%v, want login.authlete.com with 53285", got.url, got.body["apiServerId"])
	}
}

