func TestExplicitAPIServerIDIsInjected(t *testing.T) {
	rec := &recorder{}
	sdk := newSDK(rec, authlete.WithAPIServerID(99))

	create(sdk, nil)
	if got := rec.last(t).body["apiServerId"]; got != float64(99) {
		t.Errorf("create: apiServerId=%v, want 99", got)
	}
	_, _ = sdk.Service.Remove(ctx, components.ServiceRemoveIdpRequest{OrganizationID: 1, ServiceID: 9})
	if got := rec.last(t).body["apiServerId"]; got != float64(99) {
		t.Errorf("remove: apiServerId=%v, want 99", got)
	}
}

func TestPerCallAPIServerIDWins(t *testing.T) {
	rec := &recorder{}
	sdk := newSDK(rec, authlete.WithAPIServerID(53285))

	create(sdk, authlete.Int64(1))
	if got := rec.last(t).body["apiServerId"]; got != float64(1) {
		t.Errorf("apiServerId=%v, want the per-call 1", got)
	}
}

func TestIDPURLReroutesIDPOnly(t *testing.T) {
	rec := &recorder{}
	sdk := newSDK(rec, authlete.WithIDPURL("https://idp.example.com/authlete/"), authlete.WithAPIServerID(7))

	create(sdk, nil)
	if got := rec.last(t); got.url != "https://idp.example.com/authlete/api/service" || got.body["apiServerId"] != float64(7) {
		t.Errorf("create: got %s apiServerId=%v", got.url, got.body["apiServerId"])
	}
	_, _ = sdk.Audit.Get(ctx, operations.AuditEntriesGetIdpAPIRequest{})
	if got := rec.last(t).url; !strings.HasPrefix(got, "https://idp.example.com/authlete/api/audit/entries") {
		t.Errorf("audit: got %s", got)
	}
	_, _ = sdk.Service.Get(ctx, operations.ServiceGetAPIRequest{})
	if got := rec.last(t).url; got != "https://jp.authlete.com/api/123/service/get" {
		t.Errorf("main API must be unaffected: got %s", got)
	}
}

func TestOptionOrderDoesNotMatter(t *testing.T) {
	rec := &recorder{}
	// WithClient after the IdP options must not drop them.
	sdk := authlete.New(
		authlete.WithIDPURL("https://idp.example.com"),
		authlete.WithAPIServerID(7),
		authlete.WithSecurity("token"),
		authlete.WithClient(rec),
		authlete.WithRetryConfig(retry.Config{Strategy: "none"}),
	)
	create(sdk, nil)
	if got := rec.last(t); got.url != "https://idp.example.com/api/service" || got.body["apiServerId"] != float64(7) {
		t.Errorf("got %s apiServerId=%v", got.url, got.body["apiServerId"])
	}
}

func TestClientsSharingAnHTTPClientStayIsolated(t *testing.T) {
	rec := &recorder{}
	dc := newSDK(rec, authlete.WithIDPURL("https://idp.example.com"), authlete.WithAPIServerID(7))
	plain := newSDK(rec)

	create(dc, nil)
	create(plain, nil)
	create(dc, nil)
	want := []string{"https://idp.example.com/api/service", "https://login.authlete.com/api/service", "https://idp.example.com/api/service"}
	for i, w := range want {
		if rec.reqs[i].url != w {
			t.Errorf("request %d: got %s, want %s", i, rec.reqs[i].url, w)
		}
	}
	if rec.reqs[1].body["apiServerId"] != float64(53285) || rec.reqs[0].body["apiServerId"] != float64(7) {
		t.Errorf("apiServerIds: dc=%v plain=%v, want 7 and 53285", rec.reqs[0].body["apiServerId"], rec.reqs[1].body["apiServerId"])
	}
}

